-- ============================================================================
-- RESET to the Morning Market cases (decided 2026-11-27). Generated by
-- scripts/build_mm_seed.py from the case workbook; do not edit by hand.
--
-- Run AFTER migration 20261127_21_min_stock.sql, in the Supabase SQL editor.
-- One transaction: if anything fails, nothing changes.
--   1. Copies every table it empties into schema kpv_backup_20261127.
--   2. Empties, in EVERY branch: documents, transfers, stock days and
--      ledger, cases, case assignments, min/lead rules, SKUs, sizes, types.
--      Users, branches, units, closed days, settings, gold prices and the
--      audit log are kept.
--   3. Loads 11 types, 17 sizes, 235 SKUs, 235 minimums
--      and 7 cases (ຕູ້1..ຕູ້7, B-MM) checked in on 2026-11-27 with every
--      opening at 0: staff enter the real count as Stock-in.
-- ============================================================================
begin;

-- 1. Backup (a second run keeps the first backup).
create schema if not exists kpv_backup_20261127;
do $$ begin if to_regclass('kpv_backup_20261127.document_rows') is null then execute 'create table kpv_backup_20261127.document_rows as table public.document_rows'; end if; end $$;
do $$ begin if to_regclass('kpv_backup_20261127.documents') is null then execute 'create table kpv_backup_20261127.documents as table public.documents'; end if; end $$;
