select desk_id, date '2026-11-27', branch_id, 'check_in' from desks;


-- 4. Check, then one audit entry for the whole reset.
do $$ begin
  if (select count(*) from master_sku) <> 235 then raise exception 'RESET_CHECK: SKU count'; end if;
  if (select count(*) from desks) <> 7 then raise exception 'RESET_CHECK: case count'; end if;
  if (select count(*) from daily_stock_ledger) <> 235 then raise exception 'RESET_CHECK: ledger rows'; end if;
  if (select count(*) from replenishment_rule where branch_id = 'B-MM' and min_qty is not null) <> 235 then raise exception 'RESET_CHECK: minimums'; end if;
end $$;
values ('system', 'data.reset', 'B-MM', jsonb_build_object('source', 'ລາຍລະອຽດເຄື່ອງຕູ້_1-7 morning market actual.xlsx', 'date', '2026-11-27',
        'types', 11, 'sizes', 17, 'skus', 235, 'cases', 7, 'pcs', 0, 'minimums', 235, 'backup_schema', 'kpv_backup_20261127'));

commit;

-- Per case: SKUs, opening and current pieces, and the minimums it should hold.
select d.display_name as case_name, count(*) as skus,
       sum(l.opening_qty) as opening_pcs, sum(l.closing_qty) as now_pcs,
       sum(r.min_qty) as min_pcs
  from daily_stock_ledger l
  join desks d using (desk_id)
  left join replenishment_rule r on r.scope = 'sku' and r.scope_key = l.sku_id and r.branch_id = l.branch_id
 where l.ledger_date = date '2026-11-27' and l.branch_id = 'B-MM'
 group by d.display_name, d.sort_order order by d.sort_order;
